diff --git a/src/mat5.c b/src/mat5.c
index c0c37f7..fcb11f2 100644
--- a/src/mat5.c
+++ b/src/mat5.c
@@ -5310,6 +5310,8 @@ Mat_VarReadDataLinear5(mat_t *mat, matvar_t *matvar, void *data, int start, int
         Mat_Critical("Integer multiplication overflow");
         return err;
     }
+    if ( NULL != matvar->internal->data && 0 != Mat_SizeOf(matvar->data_type) )
+        nelems = matvar->nbytes / Mat_SizeOf(matvar->data_type);
     if ( (size_t)stride * (edge - 1) + start + 1 > nelems )
         return MATIO_E_BAD_ARGUMENT;

diff --git a/src/mat5.c b/src/mat5.c
index cf392ee..4a8d551 100644
--- a/src/mat5.c
+++ b/src/mat5.c
@@ -3351,6 +3351,10 @@ Mat_VarReadNumeric5(mat_t *mat, matvar_t *matvar, void *data, size_t N)
             nBytes = tag[1];
         }
     }
+    /* Numeric data is converted to the class type on read, but keep the type
+     * it was stored as when it is narrower than the class */
+    if ( Mat_SizeOf(packed_type) < Mat_SizeOf(matvar->data_type) )
+        matvar->data_type = packed_type;
     if ( nBytes == 0 ) {
         matvar->nbytes = 0;
         return err;
     }
